-- Dataset TokoKita (fiktif) untuk latihan SQL
-- Kompatibel: SQLite, PostgreSQL, MySQL. Jalankan seluruh file ini di database kosong.

DROP TABLE IF EXISTS web_events;
DROP TABLE IF EXISTS marketing;
DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS customers;

-- Pelanggan terdaftar. channel_akuisisi = dari mana pelanggan pertama kali datang.
CREATE TABLE customers (
  customer_id VARCHAR(100) PRIMARY KEY,
  nama VARCHAR(100),
  gender VARCHAR(100),
  kota VARCHAR(100),
  tgl_daftar DATE,
  channel_akuisisi VARCHAR(100)
);

-- Katalog produk. hpp = harga pokok (modal) per unit.
CREATE TABLE products (
  product_id VARCHAR(100) PRIMARY KEY,
  nama_produk VARCHAR(100),
  kategori VARCHAR(100),
  harga INTEGER,
  hpp INTEGER
);

-- Header pesanan. status: selesai / batal / retur. Hanya 'selesai' yang dihitung sebagai pendapatan.
CREATE TABLE orders (
  order_id VARCHAR(100) PRIMARY KEY,
  customer_id VARCHAR(100),
  tgl_order DATE,
  status VARCHAR(100),
  metode_bayar VARCHAR(100),
  FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

-- Detail barang per pesanan. Pendapatan baris = qty × harga_satuan × (1 − diskon).
CREATE TABLE order_items (
  item_id INTEGER PRIMARY KEY,
  order_id VARCHAR(100),
  product_id VARCHAR(100),
  qty INTEGER,
  harga_satuan INTEGER,
  diskon DECIMAL(5,2),
  FOREIGN KEY (order_id) REFERENCES orders(order_id),
  FOREIGN KEY (product_id) REFERENCES products(product_id)
);

-- Biaya iklan mingguan per channel berbayar. signup = pelanggan baru dari channel itu di minggu tsb.
CREATE TABLE marketing (
  minggu DATE,
  channel VARCHAR(100),
  biaya INTEGER,
  impressions INTEGER,
  klik INTEGER,
  signup INTEGER
);

-- Event website Jul–Okt 2026 untuk analisis funnel: view_product → add_to_cart → checkout → purchase.
CREATE TABLE web_events (
  event_id INTEGER PRIMARY KEY,
  session_id VARCHAR(100),
  tanggal DATE,
  device VARCHAR(100),
  sumber VARCHAR(100),
  event VARCHAR(100)
);

